import sys

def count_primes(n):
    if n < 3:
        return 0
    # odd-only sieve: index i represents number 2*i+1
    size = (n - 1) // 2  # numbers 1,3,5,...,< n
    sieve = bytearray([1]) * size
    sieve[0] = 0  # 1 is not prime
    limit = int(n ** 0.5) + 1
    for i in range(1, (limit // 2) + 1):
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            if start >= size:
                break
            cnt = (size - 1 - start) // p + 1
            sieve[start::p] = bytes(cnt)
    return 1 + sum(sieve)  # +1 for 2

if __name__ == "__main__":
    print(count_primes(int(sys.argv[1])))

import sys

def count_primes(n):
    # mod-6 wheel sieve: two bytearrays for residues 1 and 5 (mod 6)
    if n < 3:
        return 0
    if n < 4:
        return 1
    if n < 6:
        return 2
    la = (n + 4) // 6   # k in [0, la): 6k+1 < n
    lb = n // 6         # k in [0, lb): 6k+5 < n
    a = bytearray([1]) * la
    b = bytearray([1]) * lb
    a[0] = 0  # 1 is not prime
    lim = int(n ** 0.5) + 1
    for p in range(5, lim + 1):
        r = p % 6
        if r == 1:
            if not a[p // 6]:
                continue
        elif r == 5:
            if not b[p // 6]:
                continue
        else:
            continue
        s = (p * p) // 6
        if s < la:
            a[s::p] = bytes((la - 1 - s) // p + 1)
        m = p + ((4 * p) % 6)
        s = (p * m) // 6
        if s < lb:
            b[s::p] = bytes((lb - 1 - s) // p + 1)
    return 2 + a.count(1) + b.count(1)

if __name__ == "__main__":
    print(count_primes(int(sys.argv[1])))
